INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27501, '1 Corinthians 11:34', '1 Corinthians', 11, 34, '&nbsp;کۀ تاسو اوږى يئ نو اول بيا په کور کښې روټۍ خورئ، نو چې ستاسو رايوځائ کېدل تاسو مجرم نۀ کړى. د نورو خبرو په حقله به زۀ هدايات درکړم کله چې زۀ بيا درشم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27502, '1 Corinthians 12:1', '1 Corinthians', 12, 1, '&nbsp;نو اوس اے وروڼو او خوېندو، زۀ نۀ غواړم چې تاسو د روحانى نعمتونو په باب کښې ناخبره پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27503, '1 Corinthians 12:2', '1 Corinthians', 12, 2, '&nbsp;تاسو ته پته ده چې کله تاسو کافر وئ نو تاسو دوکه شوئ او په هغه ګونګيانو بُتانو پسې ګمراه شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27504, '1 Corinthians 12:3', '1 Corinthians', 12, 3, '&nbsp;نو په دې وجه زۀ غواړم چې تاسو په دې پوهه شئ چې د خُدائ پاک د روح په وسيله خبرې کوونکى به کله هم په عيسىٰ لعنت ونۀ وائى او بغېر د روحُ القُدس د وسيلې نه هيڅوک نۀ شى وئيلے چې عيسىٰ مالِک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27505, '1 Corinthians 12:4', '1 Corinthians', 12, 4, '&nbsp;نو د نعمتونو خو مختلف قِسمونه دى خو روح يو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27506, '1 Corinthians 12:5', '1 Corinthians', 12, 5, '&nbsp;او د خدمتونو هم مختلف قِسمونه دى خو مالِک هم هغه يو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27507, '1 Corinthians 12:6', '1 Corinthians', 12, 6, '&nbsp;خو د کارونو مختلف قِسمونه دى، خُدائ پاک هم هغه يو دے چې په مختلفو طريقو سره دا ټول کارونه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27508, '1 Corinthians 12:7', '1 Corinthians', 12, 7, '&nbsp;خو په مونږ کښې د روحُ القُدس د نعمتونو اثر د ټولو خلقو د فائدې دپاره دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27509, '1 Corinthians 12:8', '1 Corinthians', 12, 8, '&nbsp;نو يو ته د روح په وسيله د حِکمت کلام ورکړے شى او بل ته د هم هغه روح په وسيله د علميت کلام،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27510, '1 Corinthians 12:9', '1 Corinthians', 12, 9, '&nbsp;چا ته هم د هغه روح په وسيله ايمان او چا ته هم د هغه روح په وسيله د شفا ورکولو قدرت،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27511, '1 Corinthians 12:10', '1 Corinthians', 12, 10, '&nbsp;چا ته د معجزو طاقت، چا ته پېشګوئې، چا ته د مختلفو روحونو پېژندل، چا ته د نورو ژبو وئيلو قدرت او چا ته د ژبو تشريح کول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27512, '1 Corinthians 12:11', '1 Corinthians', 12, 11, '&nbsp;خو دا ټول کارونه هم هغه يو روح کوى او چا ته يې چې روح غواړى هغۀ ته يې ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27513, '1 Corinthians 12:12', '1 Corinthians', 12, 12, '&nbsp;ځکه لکه څنګه چې بدن يو دے او د دې اندامونه ډېر دى، او د بدن ټول اندامونه اګر کۀ ډېر دى خو ټول يو بدن دے، هم دغه شان مسيح هم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27514, '1 Corinthians 12:13', '1 Corinthians', 12, 13, '&nbsp;دغه شان کۀ مونږ يهوديان يُو او کۀ غېر‌يهوديان، کۀ غلامان يُو او کۀ آزاد، مونږ ټولو په يو روح کښې بپتسمه اخستې ده او خُدائ پاک زمونږ د ټولو په زړونو کښې يو روح اچولے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27515, '1 Corinthians 12:14', '1 Corinthians', 12, 14, '&nbsp;حقيقت کښې بدن د يو اندام نه نۀ وى جوړ بلکې د ډېرو نه جوړ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27516, '1 Corinthians 12:15', '1 Corinthians', 12, 15, '&nbsp;کۀ چرې پښه ووائى چې زۀ لاس نۀ يم، او زۀ د بدن حِصه نۀ يم، نو په دې وينا د هغوئ د بدن سره تعلق نۀ ختميږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27517, '1 Corinthians 12:16', '1 Corinthians', 12, 16, '&nbsp;او کۀ غوږ ووائى چې زۀ سترګه نۀ يم او زۀ د بدن حِصه نۀ يم، نو په دې وينا د هغوئ د بدن سره تعلق نۀ ختميږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27518, '1 Corinthians 12:17', '1 Corinthians', 12, 17, '&nbsp;کۀ چرې ټول بدن سترګه وے نو اورېدل به چرته وُو؟ او کۀ چرې ټول بدن غوږونه وے نو بويول به چرته وُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27519, '1 Corinthians 12:18', '1 Corinthians', 12, 18, '&nbsp;خو خُدائ پاک په بدن کښې هر يو اندام د خپلې مرضۍ په مطابق جوړ کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27520, '1 Corinthians 12:19', '1 Corinthians', 12, 19, '&nbsp;کۀ دا ټول يو اندام وے نو بيا بدن به چرته وو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27521, '1 Corinthians 12:20', '1 Corinthians', 12, 20, '&nbsp;نو اوس اندامونه ډېر دى خو بدن يو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27522, '1 Corinthians 12:21', '1 Corinthians', 12, 21, '&nbsp;نۀ سترګه لاس ته وئيلے شى چې ما ته ستا ضرورت نشته، او نۀ سر پښو ته وئيلے شى چې ما ته ستا ضرورت نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27523, '1 Corinthians 12:22', '1 Corinthians', 12, 22, '&nbsp;بلکې حقيقت کښې چې د بدن هغه اندامونه چې د نورو نه کمزورى ښکارى، هم هغه ډېر لازمى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27524, '1 Corinthians 12:23', '1 Corinthians', 12, 23, '&nbsp;او د بدن هغه اندامونه چې مونږ يې د نورو په نسبت شرم ګڼو، مونږ هم هغوئ ته زيات اهميت ورکوو، او چې د لږ احترام والا اندامونه دى نو په پردې کولو سره د هغوئ زيات احترام کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27525, '1 Corinthians 12:24', '1 Corinthians', 12, 24, '&nbsp;حالانکه زمونږ د احترام لائق اندامونو ته د داسې احترام ضرورت نشته. خو خُدائ پاک بدن داسې جوړ کړے دے چې هغه بې‌قدره اندامونو ته يې زيات عزت ورکړے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27526, '1 Corinthians 12:25', '1 Corinthians', 12, 25, '&nbsp;د دې دپاره چې په بدن کښې بې‌اتفاقى پېدا نۀ شى بلکې اندامونه د يو بل برابر خيال وساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27527, '1 Corinthians 12:26', '1 Corinthians', 12, 26, '&nbsp;کۀ يو اندام تکليف کښې وى نو ټول ورسره په تکليف کښې وى، او کۀ يو اندام عزت ومومى نو نور ټول اندامونه ورسره خوشحاله وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27528, '1 Corinthians 12:27', '1 Corinthians', 12, 27, '&nbsp;نو اوس تاسو ټول په شريکه د مسيح بدن يئ او تاسو ټول د يو بدن اندامونه يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27529, '1 Corinthians 12:28', '1 Corinthians', 12, 28, '&nbsp;او خُدائ پاک په جماعت کښې بېل بېل کسان مقرر کړل، اول رسولان، دوېم نبيان او درېم اُستاذان، بيا معجزې ښوونکى، بيا شفا ورکوونکى، مددګاران، اِنتظام کوونکى او نورې ژبې ويونکى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27530, '1 Corinthians 12:29', '1 Corinthians', 12, 29, '&nbsp;ولې ټول رسولان يُو څۀ؟ ولې ټول نبيان يُو څۀ؟ ولې ټول اُستاذان يُو څۀ؟ ولې ټول معجزې ښوونکى يُو څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27531, '1 Corinthians 12:30', '1 Corinthians', 12, 30, '&nbsp;ولې ټولو ته د شفا ورکولو نعمت ورکړے شوے دے څۀ؟ ولې ټول نورې ژبې وايو څۀ؟ ولې ټول تشريح کوونکى يُو څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27532, '1 Corinthians 12:31', '1 Corinthians', 12, 31, '&nbsp;خو تاسو د لويو نعمتونو حاصلولو دپاره خپل محنت جارى ساتئ. زۀ به اوس تاسو ته د ټولو نه يوه افضله طريقه دروښايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27533, '1 Corinthians 13:1', '1 Corinthians', 13, 1, '&nbsp;کۀ زۀ د بنى آدمو او د فرښتو په ژبو خبرې کوم خو چې مينه نۀ کوم نو زۀ ټنګېدونکے ډولکے او يا شړنګېدونکے چڼچڼے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27534, '1 Corinthians 13:2', '1 Corinthians', 13, 2, '&nbsp;او کۀ زۀ پېشګوئې کولے شم او کۀ ما ته ټول پټ رازونه او ټول عِلم معلوم وى او کۀ زما داسې ايمان وى چې غرونه خپل ځائ نه اخوا کړم، خو کۀ ما کښې مينه نۀ وى نو زۀ هيڅ شے نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27535, '1 Corinthians 13:3', '1 Corinthians', 13, 3, '&nbsp;کۀ زۀ خپل ټول مال دولت خېرات کړم او خپل بدن په سوزولو سره قربان کړم، خو کۀ ما کښې مينه نشته نو ما ته هيڅ فائده نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27536, '1 Corinthians 13:4', '1 Corinthians', 13, 4, '&nbsp;مينه صابره ده، مينه مهربانه ده، مينه چا سره کينه نۀ ساتى، مينه لافې نۀ کوى او نۀ لوئى کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27537, '1 Corinthians 13:5', '1 Corinthians', 13, 5, '&nbsp;نۀ بې‌ادبى کوى، نۀ په خپل مطلب پسې ګرځى، نۀ غصه کوى او نۀ بدګُمانى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27538, '1 Corinthians 13:6', '1 Corinthians', 13, 6, '&nbsp;مينه په بدکارۍ نۀ خوشحاليږى بلکې په رښتيا وئيلو خوشحاليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27539, '1 Corinthians 13:7', '1 Corinthians', 13, 7, '&nbsp;مينه ټول څيزونه برداشت کوى، په ټولو څيزونو يقين کوى، د ټولو څيزونو اُميد ساتى او هر څۀ زغمى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27540, '1 Corinthians 13:8', '1 Corinthians', 13, 8, '&nbsp;مينه هيڅکله نۀ ختميږى، خو پېشګويانې به ختمې شى، او د نورو ژبو نعمتونه به هم ختم شى، او عِلم به هم فنا شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27541, '1 Corinthians 13:9', '1 Corinthians', 13, 9, '&nbsp;ځکه چې زمونږ عِلم او زمونږ نبوت کامِل نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27542, '1 Corinthians 13:10', '1 Corinthians', 13, 10, '&nbsp;خو کله چې کامِل څيز راشى نو دا نامکمل څيزونه به ختم شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27543, '1 Corinthians 13:11', '1 Corinthians', 13, 11, '&nbsp;کله چې زۀ ماشوم وم ما د ماشوم غوندې خبرې کولې، زما د ماشوم په شان سوچ وو او د ماشوم په شان ناپوهه وم، خو کله چې زۀ ځوان شوم نو ما د ماشوموالى خويونه پرېښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27544, '1 Corinthians 13:12', '1 Corinthians', 13, 12, '&nbsp;ځکه اوس مونږ ته دا په شيشه کښې تت ښکارى خو بيا به يې مخامخ ووينو. اوس زما عِلم نامکمل دے خو بيا به يې پوره وپېژنم څنګه چې زۀ پوره پېژندلے شوے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27545, '1 Corinthians 13:13', '1 Corinthians', 13, 13, '&nbsp;او اوس ايمان، اُميد او مينه درې واړه پاتې کيږى او په دوئ کښې مينه افضله ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27546, '1 Corinthians 14:1', '1 Corinthians', 14, 1, '&nbsp;د مينې او محبت لمن ونيسئ او د روحانى نعمتونو او خاص د پېشګويۍ د نعمت خواهش کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27547, '1 Corinthians 14:2', '1 Corinthians', 14, 2, '&nbsp;ځکه څوک چې په نورو ژبو خبرې کوى نو هغه د نورو خلقو سره نه، بلکې د خُدائ پاک سره خبرې کوى، او بل څوک د هغۀ په خبره نۀ پوهيږى ځکه چې هغه د روح په وسيله د راز خبرې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27548, '1 Corinthians 14:3', '1 Corinthians', 14, 3, '&nbsp;خو بله دا څوک چې نورو ته نبوت کوى نو د هغوئ د ترقۍ او د ډاډګيرنى او تسلۍ دپاره يې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27549, '1 Corinthians 14:4', '1 Corinthians', 14, 4, '&nbsp;څوک چې په نورو ژبو کښې خبرې کوى هغوئ د خپل ځان ترقى کوى خو څوک چې نبوت کوى هغوئ جماعت ته ترقى ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27550, '1 Corinthians 14:5', '1 Corinthians', 14, 5, '&nbsp;اوس زۀ غواړم چې تاسو ټول په نورو ژبو خبرې وکړئ خو زما سخت خواهش دا دے چې تاسو نبوت وکړئ. ځکه څوک چې نبوت کوى هغه د نورو ژبو ويوونکو نه لوئ دے تر دې چې هغه دا ترجمه کړى نو جماعت به پرې ترقى وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27551, '1 Corinthians 14:6', '1 Corinthians', 14, 6, '&nbsp;نو زما وروڼو او خوېندو، کۀ چرې زۀ تاسو ته درشم او په نورو ژبو کښې خبرې کوم نو زما د وينا بيا تاسو ته څۀ فائده ده، ترڅو چې زۀ د کشف يا د عِلم يا د پېشګوئې يا د تعليم خبرې تاسو ته ونۀ کړم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27552, '1 Corinthians 14:7', '1 Corinthians', 14, 7, '&nbsp;تاسو بيا لکه د موسيقۍ د هغه بې‌ساه څيزونو په مثال يئ چې د کومو نه آوازونه راوځى لکه شپيلۍ يا رباب. کۀ چرې څوک هغه صفا ونۀ غږوى نو بيا د هغوئ په ساز و سرود څوک پوهېدے شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27553, '1 Corinthians 14:8', '1 Corinthians', 14, 8, '&nbsp;کۀ د بيګل آواز صفا نۀ وى نو يو فوجى به خپل ځان جنګ ته څنګه تيار کړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27554, '1 Corinthians 14:9', '1 Corinthians', 14, 9, '&nbsp;هم دغه شان کۀ ستاسو خبرې صفا نۀ وى نو بيا ستاسو په خبرو به څوک پوهه شى؟ ځکه چې بيا به تاسو هسې دېوال ته لګيا يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27555, '1 Corinthians 14:10', '1 Corinthians', 14, 10, '&nbsp;بې‌شکه چې په دُنيا کښې مختلفې ژبې دى خو يوه هم په کښې بې‌مطلبه نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27556, '1 Corinthians 14:11', '1 Corinthians', 14, 11, '&nbsp;خو کۀ چرې زۀ د کومې ژبې په مطلب نۀ پوهېږم چا ته چې خبرې کوم نو هغۀ ته به زۀ نا آشنا ښکارم او هغه به ما ته نا آشنا ښکارى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27557, '1 Corinthians 14:12', '1 Corinthians', 14, 12, '&nbsp;نو تاسو چې خپل ځان سره د روحانى نعمتونو خواهش کوئ نو داسې کوشش کوئ چې ستاسو دا نعمتونه د جماعت د ترقۍ دپاره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27558, '1 Corinthians 14:13', '1 Corinthians', 14, 13, '&nbsp;نو په دې وجه څوک چې په نورو ژبو خبرې کوى نو هغه دې ضرور د تشريح کولو د قابليت دپاره هم دُعا وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27559, '1 Corinthians 14:14', '1 Corinthians', 14, 14, '&nbsp;ځکه کۀ زۀ په نورو ژبو دُعا کوم نو زما روح خو دُعا کوى ولې عقل مې بې‌کاره دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27560, '1 Corinthians 14:15', '1 Corinthians', 14, 15, '&nbsp;نو بيا زۀ څۀ وکړم؟ زۀ به په روح کښې دُعا کوم خو ورسره به په عقل کښې هم دُعا کوم، زۀ به په روح کښې حمد و ثنا کوم خو زۀ به په عقل سره هم حمد و ثنا کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27561, '1 Corinthians 14:16', '1 Corinthians', 14, 16, '&nbsp;فرض کړه، کۀ تۀ په روح کښې حمد و ثنا کوې او يو نا آشنا کس چې هلته موجود وى نو هغه بيا ستا په شُکر ګزارۍ څنګه آمين کولے شى؟ ځکه چې هغه نا آشنا په دې نۀ پوهيږى چې تۀ څۀ وائې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27562, '1 Corinthians 14:17', '1 Corinthians', 14, 17, '&nbsp;ځکه چې تۀ خو به په ښۀ شان سره شُکر ګزارى وکړې خو ستا شُکر ګزارى بل چا ته څۀ فائده نۀ ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27563, '1 Corinthians 14:18', '1 Corinthians', 14, 18, '&nbsp;د خُدائ پاک شُکر کوم چې تاسو ټولو نه زيات زۀ په نورو ژبو کښې خبرې کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27564, '1 Corinthians 14:19', '1 Corinthians', 14, 19, '&nbsp;خو په جماعت کښې هغه پينځۀ مقصدى خبرې د دې نه بهترې ګڼم چې نورو ته ترې فائده ورسى، د هغه لس زره خبرو نه چې په نورو ژبو کښې يې وکړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27565, '1 Corinthians 14:20', '1 Corinthians', 14, 20, '&nbsp;اے زما وروڼو او خوېندو، په خپله پوهه کښې ماشومان مۀ جوړېږئ، بدۍ ته ماشومان شئ خو په پوهه کښې بالغان شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27566, '1 Corinthians 14:21', '1 Corinthians', 14, 21, '&nbsp;په تورات کښې ليکلى دى چې، ”زۀ به دې قوم ته په عجيبه ژبو او په غېرو شونډو خبرې وکړم خو بيا به هم هغوئ ما ته غوږ ونۀ نيسى. دا مالِک فرمائى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27567, '1 Corinthians 14:22', '1 Corinthians', 14, 22, '&nbsp;نو روحانى ژبې د ايماندارانو دپاره نه، بلکې د بې‌ايمانانو دپاره نښې دى او پېشګوئې کول د بې‌ايمانانو دپاره نه، بلکې د ايماندارانو دپاره دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27568, '1 Corinthians 14:23', '1 Corinthians', 14, 23, '&nbsp;نو کۀ ټول جماعت راغونډ وى او په نورو ژبو لګيا وى نو کۀ نا آشنا يا بې‌ايمانه دننه راشى نو ولې هغوئ به تاسو ته ليونى ونۀ وائى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27569, '1 Corinthians 14:24', '1 Corinthians', 14, 24, '&nbsp;خو کۀ تاسو ټول نبوت کوئ کۀ يو بې‌ايمانه يا نا آشنا دننه راشى نو د دې په اورېدو به هغه په دې قائل شى چې ګناه ګار شوے يم او هغه بيان به د دۀ جاج واخلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27570, '1 Corinthians 14:25', '1 Corinthians', 14, 25, '&nbsp;د بې‌ايمانه د زړۀ د راز څرګندېدو نه پس به هغه کس د خُدائ پاک په وړاندې په سجده شى او د هغۀ عبادت به وکړى، او اِقرار به وکړى چې، ”بې‌شکه خُدائ پاک په تاسو کښې دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27571, '1 Corinthians 14:26', '1 Corinthians', 14, 26, '&nbsp;نو اے وروڼو او خوېندو، لنډه دا، هر کله چې تاسو عبادت له راجمع کېږئ نو په تاسو کښې دې څوک حمد، يا تعليم، يا کشف يا په نورو ژبو خبرې او يا د نورو ژبو تشريح په ترتيب سره کوئ او دا هر يو کار د جماعت د ترقۍ دپاره کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27572, '1 Corinthians 14:27', '1 Corinthians', 14, 27, '&nbsp;کۀ څوک په نورو ژبو خبرې کوى نو صرف دوه يا زيات نه زيات درې کسان دې نمبر په نمبر خبرې وکړى او يو کس دې يې تشريح کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27573, '1 Corinthians 14:28', '1 Corinthians', 14, 28, '&nbsp;خو کۀ څوک تشريح کوونکے نۀ وى نو هغوئ دې په جماعت کښې چپ پاتې شى او خپل ځان او د خُدائ پاک سره دې خبرې وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27574, '1 Corinthians 14:29', '1 Corinthians', 14, 29, '&nbsp;نو تاسو صرف دوه يا درې نبيانو ته د خبرو موقع ورکوئ، او نور دې په آرام سره د هغۀ د خبرو جاج واخلى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27575, '1 Corinthians 14:30', '1 Corinthians', 14, 30, '&nbsp;خو کۀ په حاضرو کسانو کښې چا ته د مالِک نه کشف مِلاو شى نو کوم کس چې د اول نه په نبوت کولو لګيا دے هغه دې خاموش شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27576, '1 Corinthians 14:31', '1 Corinthians', 14, 31, '&nbsp;ځکه هر يو نمبر په نمبر نبوت کوئ، نو چې تاسو ټولو ته هدايت او ډاډګيرنه حاصله شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27577, '1 Corinthians 14:32', '1 Corinthians', 14, 32, '&nbsp;او نبيان د نبيانو د روحونو تابع وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27578, '1 Corinthians 14:33', '1 Corinthians', 14, 33, '&nbsp;ځکه چې خُدائ پاک د بد نظمۍ نه، بلکې د امن خُدائ دے. لکه چې د مقدسينو په ټولو جماعتونو کښې دے', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27579, '1 Corinthians 14:34', '1 Corinthians', 14, 34, '&nbsp;ښځې دې په جماعتونو کښې خاموشه وى. ځکه چې هغوئ ته د خبرو کولو اجازت نشته بلکې هغوئ دې تابعدارې وى څنګه چې شريعت هم وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27580, '1 Corinthians 14:35', '1 Corinthians', 14, 35, '&nbsp;کۀ هغوئ په څۀ خبره ځان پوهول غواړى نو هغوئ دې د خپلو خاوندانو نه په کور کښې تپوس کوى. ځکه چې په جماعت کښې د ښځې دپاره خبره کول د شرم خبره ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27581, '1 Corinthians 14:36', '1 Corinthians', 14, 36, '&nbsp;ولې د خُدائ پاک کلام تاسو جوړ کړے دے څۀ؟ يا ولې دا صرف تاسو ته رارسېدلے دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27582, '1 Corinthians 14:37', '1 Corinthians', 14, 37, '&nbsp;کۀ څوک د نبوت، يا د روحانى نعمتونو د لرلو دعوىٰ وکړى نو هغه دې پوهه شى چې کومې خبرې زۀ تاسو ته ليکم هغه د مالِک حکم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27583, '1 Corinthians 14:38', '1 Corinthians', 14, 38, '&nbsp;هر څوک چې دا نۀ منى، نو هغه به هم نا منظوره کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27584, '1 Corinthians 14:39', '1 Corinthians', 14, 39, '&nbsp;نو اے زما ملګرو، د نبوت کولو خواهش کوئ او په نورو ژبو خبرې کوونکى مۀ منع کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27585, '1 Corinthians 14:40', '1 Corinthians', 14, 40, '&nbsp;خو هر يو کار صحيح او ترتيب سره کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27586, '1 Corinthians 15:1', '1 Corinthians', 15, 1, '&nbsp;نو زما وروڼو او خوېندو، زۀ به اوس تاسو ته هغه زيرے درياد کړم چې ما تاسو ته درکړے وو، کوم چې تاسو قبول کړے وو او په کوم چې تاسو قائم هم يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27587, '1 Corinthians 15:2', '1 Corinthians', 15, 2, '&nbsp;او د کوم په وسيله چې تاسو خلاصون حاصلوئ کۀ چرې تاسو زما په درکړى زېرى قائم يئ، کۀ نۀ يئ نو ستاسو ايمان راوړل عبث وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27588, '1 Corinthians 15:3', '1 Corinthians', 15, 3, '&nbsp;ما د ټولو نه اول هغه اهم خبره تاسو ته در ورسوله کومه چې ما ته رارسېدلې وه چې د صحيفو په مطابق مسيح زمونږ د ګناهونو دپاره مړ شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27589, '1 Corinthians 15:4', '1 Corinthians', 15, 4, '&nbsp;او هغه ښخ شو او د کِتاب مقدس په مطابق هغه په درېمه ورځ بيا ژوندے پاڅېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27590, '1 Corinthians 15:5', '1 Corinthians', 15, 5, '&nbsp;او هغه اول پطروس او بيا دولسو کسانو ته ښکاره شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27591, '1 Corinthians 15:6', '1 Corinthians', 15, 6, '&nbsp;بيا هغۀ يو ځل د پينځو سوو نه زيات وروڼو او خوېندو ته ښکاره شو چې په هغوئ کښې زيات کسان تر اوسه ژوندى دى او ځينې مړۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27592, '1 Corinthians 15:7', '1 Corinthians', 15, 7, '&nbsp;بيا هغه يعقوب ته ښکاره شو او د دې نه پس ټولو رسولانو ته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27593, '1 Corinthians 15:8', '1 Corinthians', 15, 8, '&nbsp;د ټولو نه په آخر کښې هم ما ته ښکاره شو، زۀ چې بې‌مودې پېدا شوے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27594, '1 Corinthians 15:9', '1 Corinthians', 15, 9, '&nbsp;زۀ په رسولانو کښې د ټولو نه ورکوټے يم تر دې چې د رسول بللو لائق هم نۀ يم ځکه چې ما د خُدائ پاک جماعت زورَولے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27595, '1 Corinthians 15:10', '1 Corinthians', 15, 10, '&nbsp;خو زۀ چې هر څۀ يم هغه د خُدائ پاک په فضل يم، او هغه فضل چې په ما وشو هغه بې‌فائدې نۀ وو. په حقيقت کښې ما د هغوئ ټولو نه زياته خوارى کړې ده. اګر کۀ دا ما ونۀ کړه بلکې د خُدائ پاک په هغه فضل وشوه چې په ما دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27596, '1 Corinthians 15:11', '1 Corinthians', 15, 11, '&nbsp;نو بيا په دې کښې دومره فرق نۀ پرېوځى کۀ چرې زۀ بيان وکړم او يا کۀ هغوئ، خو مونږ دواړه يو زيرے بيانوو په کوم چې ستاسو د اول نه ايمان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27597, '1 Corinthians 15:12', '1 Corinthians', 15, 12, '&nbsp;نو اوس کۀ مونږ زيرے بيانوو چې مسيح له مړو نه بيا راژوندے شوے دے نو بيا په تاسو کښې ځينې دا څنګه وائى چې د مړو بيا ژوندى کېدل نشته؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27598, '1 Corinthians 15:13', '1 Corinthians', 15, 13, '&nbsp;کۀ د مړو بيا ژوندى کېدل نۀ وے نو بيا خو مسيح هم راژوندے شوے نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27599, '1 Corinthians 15:14', '1 Corinthians', 15, 14, '&nbsp;او کۀ مسيح بيا نۀ وى راژوندے شوے نو بيا زمونږ پېغام عبث دے او ستاسو ايمان هم بې‌فائدې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27600, '1 Corinthians 15:15', '1 Corinthians', 15, 15, '&nbsp;بلکې مونږ د خُدائ پاک دروغژن ګواهان شو ځکه چې مونږ د خُدائ پاک په حقله دا ګواهى ورکړې وه چې هغۀ مسيح راژوندے کړو. کۀ چرې مړى بيا نۀ راژوندى کيږى نو بيا هغه يې هم نۀ دے ژوندے کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');